import click
from click.testing import CliRunner
r = CliRunner()

def show(label, cmd, args=(), **kw):
    res = r.invoke(cmd, list(args), standalone_mode=False, **kw)
    print(f"{label}: {res.return_value!r} exc={res.exception!r}")

# context_settings default_map
@click.command(context_settings=dict(default_map={"flag": True}))
@click.option("--flag", is_flag=True)
def c1(flag): return flag
show("ctxsettings dm", c1)

# eager flag + dm
@click.command()
@click.option("--flag", is_flag=True, is_eager=True)
def c2(flag): return flag
show("eager flag dm", c2, default_map={"flag": True})

# expose_value False
@click.command()
@click.option("--flag", is_flag=True, expose_value=False)
def c3(): return "ok"
show("expose_value False dm", c3, default_map={"flag": True})

# callback
@click.command()
@click.option("--flag", is_flag=True, callback=lambda c,p,v: f"cb{v}")
def c4(flag): return flag
show("callback dm", c4, default_map={"flag": True})

# group with flag on group, nested dm
@click.group()
@click.option("--flag", is_flag=True)
def g(flag): pass
@g.command()
def sub(): pass
res = r.invoke(g, ["sub"], default_map={"flag": True}, standalone_mode=False)
print("group flag nested dm:", res.return_value, res.exception)

# flag with multiple opts
@click.command()
@click.option("--flag", "-f", is_flag=True)
def c5(flag): return flag
show("multi opts dm", c5, default_map={"flag": True})

# flag with secondary + dm False
@click.command()
@click.option("--flag/--no-flag", default=True)
def c6(flag): return flag
show("pair default True dm False", c6, default_map={"flag": False})

# non-bool flag with default set + dm
