@click.option("--upper", "t", flag_value="upper", default="upper")
def c7(t): return t
show("nonbool flag default upper, no dm", c7)
show("nonbool flag default upper, dm lower", c7, default_map={"t": "lower"})

# flag with envvar set but env missing + dm
@click.command()
@click.option("--flag", is_flag=True, envvar="NOPE")
def c8(flag): return flag
show("envvar unset + dm", c8, default_map={"flag": True})

